    "slug": "tangram-puzzles-spatial-reasoning-toddlers",
    "title": "Geometric Tangrams & Wooden Puzzles: Laying Early Math Foundations",
    "category": "Preschool & Pre-K Readiness",
    "readTime": "5 min read",
    "date": "2026-04-12",
    "image": "/images/gallery/numbers-puzzle-math.jpg",
